def flatten_sections(rows_obj, cols, section=''):
    rows=rows_obj if isinstance(rows_obj,list) else rows_obj.get('Row',[])
    out=[]
    for r in rows:
        t=r.get('type','')
        if t=='Section':
            h=r.get('Header',{}).get('ColData',[])
            s=(h[0].get('value','') if h else section)
            inner=r.get('Rows')
            if inner:
                out.extend(flatten_sections(inner, cols, s))
        elif t=='Data':
            vals=[c.get('value','') for c in r.get('ColData',[])]
            rec=dict(zip(cols,vals))
            rec['section']=section
            out.append(rec)
        else:
            inner=r.get('Rows')
            if inner:
                out.extend(flatten_sections(inner, cols, section))
    return out
